class Lesson {
  final String title, goal, steps, script, objection, response, practice;
  const Lesson(this.title,this.goal,this.steps,this.script,this.objection,this.response,this.practice);
}
const lessons = <Lesson>[
 Lesson('استقبال العميل','كسب ثقة العميل خلال اللحظات الأولى','ابدأ بتحية ودودة وابتسامة طبيعية. امنح العميل مساحة. اسأله عن هدف زيارته بدل تقديم عرض طويل. لاحظ إن كان يرغب في المساعدة فورًا أو يفضل الاستكشاف.','حياك الله، تبحث عن جهاز محدد أو نساعدك تختار الأنسب لاستخدامك؟','أنا بس أتفرج.','أكيد، خذ راحتك. أنا قريب منك إذا احتجت أي معلومة.','طبّق افتتاحيتين مع ٣ عملاء وقارن استجابتهم.'),
 Lesson('فهم احتياج العميل','تقديم ترشيح مناسب بناءً على احتياج حقيقي','ابدأ بالسؤال عن الجهاز الحالي ثم المشكلة الأساسية. اسأل عن الاستخدام اليومي وأولويتين والميزانية. أعد صياغة الإجابات للتأكد قبل ترشيح جهاز.','وش أكثر شيء تحتاج يتحسن عن جوالك الحالي: التصوير أو البطارية أو شيء ثاني؟','ما أدري وش أحتاج بالضبط.','خلنا نبدأ باستخدامك اليومي، وبعدها نحدد الخيار المناسب.','نفّذ مقابلة احتياج مع ٣ عملاء دون ذكر مواصفات أولًا.'),
 Lesson('الاستماع وطرح الأسئلة','اكتشاف المعلومات التي لا يذكرها العميل مباشرة','استخدم الأسئلة المفتوحة ثم أسئلة المتابعة. لا تقاطع العميل. لخّص ما فهمته واطلب تأكيده. تجنب افتراض أن السعر هو الأولوية للجميع.','إذا فهمتك صح، أهم شيء عندك كاميرا جيدة وجهاز يعيش معك سنوات، صحيح؟','أبي أفضل جهاز.','أفضل جهاز يختلف حسب استخدامك؛ وش أكثر ميزة تهمك؟','استخدم سؤالين مفتوحين وسؤال متابعة مع عميلين.'),
 Lesson('أنواع العملاء','تكييف أسلوب البيع حسب شخصية العميل','العميل المستعجل يحتاج ملخصًا سريعًا؛ المتردد يحتاج طمأنة وأدلة؛ التقني يحتاج تفاصيل موثقة؛ المهتم بالسعر يحتاج تفسير القيمة. تجنب التصنيفات الجامدة واستجب لسلوك الشخص الفعلي.','بما إن وقتك محدود، أعطيك أهم ميزتين مرتبطتين باستخدامك.','أبي أشوف كل التفاصيل.','ممتاز، نبدأ بالأهم بالنسبة لك ونراجع التفاصيل نقطة نقطة.','جرّب أسلوبين مختلفين حسب وقت العميل واهتمامه.'),
 Lesson('تحويل المواصفات إلى فوائد','ربط كل معلومة تقنية بقيمة عملية','ابدأ باحتياج العميل. اذكر الميزة الصحيحة ثم وضح أثرها في حياته. ادعم الشرح بتجربة أو مثال، واسأله إن كانت الفائدة تهمه. لا تبالغ في النتائج.','بما إنك تصور كثير، خلنا نجرب الكاميرا بنفسك ونشوف النتيجة.','كل الأجهزة مواصفاتها قوية.','صحيح، لذلك الأهم كيف تخدم المواصفات استخدامك أنت.','حوّل ٣ مواصفات إلى فوائد شخصية واضحة.'),
 Lesson('العرض العملي','جعل العميل يختبر القيمة بنفسه','اختر تجربة قصيرة مرتبطة باحتياج العميل. اشرح ما سيجربه، ثم سلّمه الجهاز واطلب رأيه. لا تعرض مزايا غير مرتبطة بحاجته.','خلنا نصور نفس المشهد، وبعدها أنت احكم على النتيجة.','ما أحتاج أجرب.','أكيد، أشرح لك الفكرة بسرعة وإذا حبيت نجربها لاحقًا.','نفّذ عرضين عمليين واترك العميل يجرب.'),
 Lesson('فن الإقناع','بناء اقتناع على الدليل والثقة','ابدأ بالمشكلة، ثم الحل المناسب، ثم دليل أو تجربة. استخدم لغة واضحة. اسأل العميل عن رأيه بدل إغراقه بالمعلومات. تجنب المقارنات المضللة والضغط.','هذه الميزة قد تناسب استخدامك، خلنا نشوف كيف تعمل على أرض الواقع.','ما اقتنعت.','وش النقطة اللي ما زالت غير واضحة؟ خلنا نراجعها مع بعض.','استخدم تسلسل المشكلة ثم الحل ثم الدليل مع عميلين.'),
 Lesson('معالجة الاعتراضات','تحويل الاعتراض إلى حوار مفيد','استمع للاعتراض كاملًا. اعترف بأهمية القلق، واسأل عن السبب المحدد. قدم معلومة موثوقة أو تجربة، ثم تحقق من زوال الاعتراض.','أتفهم حرصك على التطبيقات. وش التطبيقات الأساسية اللي تعتمد عليها؟ خلنا نتحقق من توفرها.','السعر مرتفع.','أتفهمك. هل المقارنة مع ميزانية محددة أو مع جهاز آخر؟ نراجع القيمة حسب استخدامك.','تدرب على اعتراض السعر والتطبيقات والمنافس.'),
 Lesson('المقارنة الاحترافية','مقارنة الأجهزة بعدل ودقة','حدد احتياج العميل أولًا. قارن المواصفات الموثقة للطرازين مع ذكر نقاط القوة والقيود بإنصاف. فرّق بين الأرقام والتجربة الفعلية.','خلنا نقارن في الشيء اللي يهمك فعلًا بدل ما نقارن أرقامًا كثيرة.','المنافس أفضل في كل شيء.','يمكن يكون أنسب في جوانب معينة؛ نحدد أولوياتك ونقارنها بمعلومات مؤكدة.','جهّز مقارنة موضوعية لميزة واحدة من مصدر رسمي.'),
 Lesson('الاحترافية ولغة الجسد','بناء حضور مهني مريح','قف بوضعية مريحة، حافظ على تواصل بصري مناسب، واستمع دون مقاطعة. احترم المساحة الشخصية ونبرة العميل. لا تخترع إجابة عندما تجهل معلومة.','سؤال ممتاز، خلني أتأكد من المواصفات الرسمية حتى أعطيك إجابة دقيقة.','أنت مو متأكد من المعلومة؟','صحيح، وأفضّل أتأكد بدل أعطيك معلومة غير دقيقة.','اطلب من زميل ملاحظة وضوحك ولغة جسدك.'),
 Lesson('إغلاق البيع','تسهيل القرار دون ضغط','راجع الاحتياج والفوائد التي اقتنع بها العميل. اسأله عن أي تحفظ متبقٍ. إذا كان مستعدًا، اقترح الخطوة التالية مثل اختيار اللون والسعة. احترم عدم استعداده.','إذا كل النقاط واضحة لك، تحب نشوف اللون والسعة المناسبة؟','أحتاج أفكر.','أكيد، خذ وقتك. هل فيه نقطة تحب أوضحها قبل ما تقرر؟','تدرب على إغلاق استشاري مع عميلين مهتمين.'),
 Lesson('المتابعة بعد الزيارة','الحفاظ على الثقة بعد مغادرة العميل','اطلب إذن التواصل أولًا. دوّن احتياج العميل بإيجاز وبما يحترم الخصوصية. أرسل معلومات مفيدة لا رسائل متكررة. توقف إذا لم يرغب العميل بالمتابعة.','إذا يناسبك، أرسل لك ملخص الخيارات اللي شفناها اليوم؟','ما أبي رسائل.','أكيد، أحترم رغبتك وشكرًا لزيارتك.','اكتب رسالة متابعة قصيرة بعد أخذ الموافقة.'),
];
